// UploadFile is the resolver for the uploadFile field.
func (r *mutationResolver) UploadFile(ctx context.Context, file graphql.Upload) (*model.File, error) {
	stream, err := r.File.UploadFile(ctx)
	if err != nil {
		return nil, err
	}

	err = stream.Send(&filev1.UploadFileRequest{
		Data: &filev1.UploadFileRequest_Metadata{
			Metadata: &filev1.FileMetadata{Filename: file.Filename, MimeType: file.ContentType},
		},
	})
	if err != nil {
		return nil, err
	}

	// 2. данные кусками
	buf := make([]byte, 64*1024)
	for {
		n, readErr := file.File.Read(buf)
		if n > 0 {
			err := stream.Send(&filev1.UploadFileRequest{
				Data: &filev1.UploadFileRequest_ChunkData{ChunkData: buf[:n]},
			})
			if err != nil {
				break
			}
		}
		if readErr == io.EOF {
			break
		}
		if readErr != nil {
			return nil, readErr
		}
	}

	res, err := stream.CloseAndRecv()
	if err != nil {
		return nil, err
	}

	return &model.File{
		ID:   res.FileId,
		Name: file.Filename,
		Size: int32(res.BytesUploaded),
		URL:  "/files/" + res.FileId,
	}, nil

	// panic(fmt.Errorf("not implemented: UploadFile - uploadFile"))
}

